        t = sample_src(uv + o + vec2f(1.0, -5.0) * px); w = sin(w * 1.17 + t.r);
        t = sample_src(uv + o + vec2f(-5.0, 0.0) * px); w = cos(w * 1.24 + t.g);
        t = sample_src(uv + o + vec2f(2.0, 5.0) * px); w = exp(-abs(w * 1.31 + t.b));
        t = sample_src(uv + o + vec2f(-4.0, -1.0) * px); w = sqrt(abs(w * 1.38 + t.a) + 0.01);
        t = sample_src(uv + o + vec2f(3.0, 4.0) * px); w = sin(w * 1.45 + t.r);
        t = sample_src(uv + o + vec2f(-3.0, -2.0) * px); w = cos(w * 1.52 + t.g);
        t = sample_src(uv + o + vec2f(4.0, 3.0) * px); w = exp(-abs(w * 1.59 + t.b));
        t = sample_src(uv + o + vec2f(-2.0, -3.0) * px); w = sqrt(abs(w * 1.66 + t.a) + 0.01);
        acc += vec4f(w, w, w, 1.0);
    }
    return vec4f(acc.rgb / 1024.0, src.a);
}
